import { snHttpFactory } from "sn-http-request";
import { hello } from "./index";

const snHttp = snHttpFactory();

export default () =>
  snHttp
    .request({
      method: "GET",
      url: "/api/now/ui/user/current_user",
    })
    .then(function (response) {
      console.log(response);
      hello();
    });
